const structureSample = {"base": {"title": "杯盖与降温 · 完成态", "assets": [{"id": "f6af246025b74069", "name": "课堂测量记录.bib", "sha": "bcf7dd67368a14dffa858bb07126afca46f3e6ae55e80893422c97c7eb353cfe", "role": "书目导入", "version": "v1", "time": "2026-11-20T03:42:39+00:00"}, {"id": "dc1a573dd2134a10", "name": "课堂测量记录.pdf", "sha": "51320800fba9ca9e44f6c4c03268c3b973e3cc72e8722023703f4bf897c01a60", "role": "文献原件", "version": "v2", "time": "2026-11-20T03:42:39+00:00"}, {"id": "36ef6b7eb6eb46f1", "name": "温度记录.csv", "sha": "11095eaf100f28e8f5f579d0523964157a22ccff324be135f3ce08c453b191b8", "role": "参考资料", "version": "v3", "time": "2026-11-20T03:42:40+00:00"}, {"id": "b803e79a42354c5c", "name": "交叉实验.csv", "sha": "44b907be94d9763b96a6853e5853d7ef14c5b0588bfaf069153ecff3a072208b", "role": "参考资料", "version": "v3", "time": "2026-11-20T03:42:40+00:00"}, {"id": "2c5146d1bb9a4ec1", "name": "cup-setup.png", "sha": "be17d5ef08ffc9fb55f3553397e270d43f339c5269a388b0fbe8f8289e5be05a", "role": "论文插图", "version": "v3", "time": "2026-11-20T03:42:40+00:00", "figurePath": "figures/cup-setup.png"}, {"id": "5f5e22cb50404078", "name": "endpoints.png", "sha": "e0c368d0cfa1ee93475101f1c5c540ed20b5857f8d5c46bdaeea12a4e440cdee", "role": "论文插图", "version": "v4", "time": "2026-11-20T03:42:40+00:00", "figurePath": "figures/endpoints.png"}, {"id": "494338893d5e427b", "name": "crossover.png", "sha": "2cf8b2370917306ca9c6d0b65cf1687903cd4443267acffe523479325a7225dd", "role": "论文插图", "version": "v5", "time": "2026-11-20T03:42:40+00:00", "figurePath": "figures/crossover.png"}, {"id": "984cb548335949e6", "name": "写作记录-question-v8.md", "sha": "65a45cda1834b00d5966ccb0c55b4cf21c9ea3c5dddad8f4a81c6f1e0dbb0d89", "role": "写作留档", "version": "v8", "time": "2026-11-20T03:42:40+00:00"}, {"id": "fef322acd97644cb", "name": "写作记录-question-v10.md", "sha": "61677c56ed4dd09356243e0d72cbf3b486bab3d4a2c917837da911c0e6078bf1", "role": "写作留档", "version": "v10", "time": "2026-11-20T03:42:40+00:00"}, {"id": "12e7098d0465447c", "name": "Draft-01-审阅回稿.docx", "sha": "0e338b2754b5c8002a81004098c532e8e90fb7da56780e2c68e48d453e07a360", "role": "对旧版的反馈", "version": "v34", "time": "2026-11-20T03:42:40+00:00"}], "settings": {"outline": "作者先搭建", "allVersions": false, "ganttVersions": false, "saveSeconds": 60, "external": false, "floatingToc": {"enabled": true, "side": "left", "maxDepth": 6, "collapseDepth": 2, "pinned": false, "hover": false, "tooltip": true, "wrap": false, "hideFirst": false, "progress": true, "barWidth": 32}, "logicStyle": "symbols", "figureLabelStyle": "zh", "manuscriptAuthor": "ManuScript 示例课堂", "citationStyle": "apa"}, "figureAliases": {"figures/cup-setup.png": "2c5146d1bb9a4ec1", "figures/endpoints.png": "5f5e22cb50404078", "figures/crossover.png": "494338893d5e427b"}, "notes": []}, "snapshots": {"01": {"blocks": [{"id": "question", "title": "杯盖能解释多少温差？固定杯具与同杯换盖的两项模拟冷却研究", "text": "ManuScript 示例课堂\n\n**原创模拟研究**　本文的装置、温度读数和审阅意见均为写作练习构造；未开展实物实验。", "format": "md", "parent": null, "purpose": "盖上杯盖，水会凉得更慢吗？", "chain": [], "writer": "author", "status": "撰写中", "rev": 3, "refs": [], "start": "", "due": "", "origin": null, "writingPlan": {"steps": [{"id": "question", "reason": "提出可检验的问题", "node": {"id": "question", "p": "root", "t": "研究问题", "detail": "盖上杯盖，水会凉得更慢吗？", "assets": ["question"]}}, {"id": "observation", "reason": "先比较两杯的实际读数", "node": {"id": "observation", "p": "root", "t": "温度观察", "detail": "按轮比较 0、5、10 分钟的温度。", "ideaOnly": true}}], "brief": "用十分钟内的温度变化比较两套杯具，再判断测量能说明什么。"}}, {"id": "021b38607b094735", "title": "摘要", "text": "将有盖玻璃杯与敞口陶瓷杯同时摆上桌，十分钟后的温差能否说明加盖有用？我们构造了两个可以逐条复算的数据集。研究一在六轮配对观察中保持两套装置不变。第 5 和第 10 分钟的平均温差分别为 1.83 和 3.83 °C，后者在各轮介于 3 至 5 °C。研究二沿用这两只杯子，在八个区组内各安排两个时段，让每只杯子各经历一次有盖和敞口条件。按同杯的两次终点相减，加盖时玻璃杯平均高 1.69 °C，陶瓷杯平均高 1.31 °C；陶瓷杯有一个区组两次读数持平。两只杯的加盖差值之差平均为 0.38 °C，逐组却有正有负。换盖比较回答了固定装置比较留下的问题，同时暴露出时段变化和杯体取样的限制。所有温度均为写作教学构造；本文展示如何定义比较、追溯原始记录和约束结论。\n\n**关键词**　配对设计、交叉比较、热水冷却、重复测量、模拟数据", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "a04159c4e1c34989", "title": "1 Intro", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "630964f150d548a5", "title": "1.1 比较对象与研究动机", "text": "把两杯水同时放到桌上，十分钟后用温度计读数，比请人判断哪杯“更烫”更容易复核。困难在于确定比较对象。若一只是带盖的玻璃杯，另一只是敞口的陶瓷杯，那么“哪一套杯具里的水保持得更热”和“单独加盖能让水保持多热”需要两种不同的实验设计。\n\n研究一先回答前一个问题。我们关心差异在各轮的方向是否一致，也关心它是到结束时才出现，还是在中途已经可见。为此，每轮都保留同一时刻的两杯读数，并将杯子左右换位。这样，一轮共同的起始条件可以随这一对读数一起保留。杯壁和盖子则始终成套使用；这一安排决定了后文能够解释哪一种差别。\n\n设想读者要作两个决定。第一个是从桌上的两套装置中挑一套，让水在十分钟后温度更高。读者可以直接比较同桌、同时开始的两个终点。第二个是手头已经有一只杯，要决定是否给它配盖。此时最相关的参照物是这只杯敞口时的表现。两种决定使用同一支温度计、同一种单位，所需的对照却不同。这也是本文把研究分两步进行的原因。\n\n全文借鉴定量研究报告规范中关于设计、分析单位、结果与限制的报告项目 [@Appelbaum2018]。研究一保留一张较容易误读的记录，研究二有意补上研究一缺少的条件。为避免用模拟材料冒充实验，下面把条件的设定、读数的构造和从读数算出的统计量分别交代。文中外部文献用于说明研究问题的来由和比较方法，所有表格内的数字来自随文提供的两份数据。", "format": "md", "parent": "a04159c4e1c34989", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "e374614296a34516", "title": "1.2 文献背景与研究问题", "text": "一杯热水冷却时，热量可以经水面、杯壁等多条途径传向周围。已有研究通过汤碗和咖啡杯讨论了日常容器中液体的冷却过程 [@Ferreira2024]。针对小杯热水的研究也把蒸发纳入冷却分析 [@Shayunusov2025]。这给出了一个值得检验的方向：改变杯口覆盖状态后，十分钟终温可能改变。要判断某次温差究竟有多少来自蒸发，还需知道水分损失及其他传热途径。仅有温度读数无法完成这项分解。\n\n杯壁、杯口与水面之间的关系也影响观察的解释。两只同容量杯子可以有不同的壁厚、杯口面积与干燥质量。相同的初始水温保证两份水从相同读数出发，却没有保证杯壁在头一分钟吸收相同的热量。即便两只杯子都敞口，也可能出现终点温差。本文故意把第一项研究的装置差别画在图上，使读者能在看结果之前就判断比较中有哪些因素一道变化。\n\n由此提出三个顺次收窄的问题。其一，两套指定装置的水温在前后两个五分钟怎样分开？其二，同一只杯子的盖子状态改变后，十分钟终点相差多少？其三，两只具体杯子的加盖差是否一致？前两个问题分别对应研究一和研究二的主要比较。第三问须先各算一个同杯差，再比较两个差；它作为探索性分析单列，因为每种材质在本例中只有一只实物原型。", "format": "md", "parent": "a04159c4e1c34989", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "a26c6ef5d9644cb6", "title": "2 Method", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "6a02fcf487b54a40", "title": "2.1 设计与数据构造", "text": "本例的“轮”指一次同时开始的双杯观察，“区组”指紧邻的两个双杯时段。两项研究均使用同一只玻璃杯与同一只陶瓷杯的虚构原型。我们先指定研究一有六轮、研究二有八个区组，再手工给出符合 0.5 °C 网格的读数，没有从文献表格摘录数值，也没有拟合真实仪器数据。选择八组是为了两种先后次序各占四组，并使读者能手工核对每一组。样本大小没有经过基于检验效能的计算。\n\n读数有意包含若干不同情况：研究一有一轮两套装置差别较大；研究二有同杯换盖后读数相同的区组，也有陶瓷杯加盖差大于玻璃杯的区组。这样的安排可以检查分析是否保留例外。数据没有缺测，各行均参与对应汇总。读者拿到的是整张设计好的教学数据表，无法据此估计某种现象在现实中的发生概率。\n\n在记录单位与分析单位之间作区分，有助于避免把重复读数误当作独立样本。一项讨论细胞和动物实验的方法研究详细区分了实验单位与重复观测 [@Lazic2018]。落实到这里，研究一有十二条杯次轨迹、三十六个温度读数，但报告的是六个同时配对的轮次。研究二有三十二个终点，构成八组，每组各给出一个玻璃杯同杯差和一个陶瓷杯同杯差。整篇论文始终只有两只不同的杯子。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "6677a7b0ad7545c9", "title": "2.2 固定杯具的配对观察", "text": "两套杯具的配置见[图 1](#fig-0000000000000001)。课堂装置记录固定了杯盖与杯体的配对关系 [@CupLog#3baabb20d3d098cfeb9396e1]。A 为带盖玻璃杯，B 为敞口陶瓷杯。每轮开始前先倒空两杯，待杯体回复室温，再分别注入 200 mL 水。两杯均读到 80.0 °C 时启动该轮计时。奇数轮把 A 放在左侧，偶数轮对换位置，六轮各使用左右位置三次。\n\n![A 杯带盖且为玻璃杯，B 杯敞口且为陶瓷杯](figures/cup-setup.png) <a id=\"fig-0000000000000001\"></a>\n\n**图注** A、B 两套固定配置。左右位置逐轮交换，杯盖状态和杯体材质始终成对出现。\n\n每轮在起始、第 5 分钟和第 10 分钟各记录一次水温，读数按 0.5 °C 为步长记入原始表。六轮使用同一对杯具，每轮换水。一个观测单位是一轮中同时比较的两杯，三个时点用于描述这一轮的过程。将同一杯的三个读数分别计为三个独立样本，会夸大实际的重复次数。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 1, "refs": [], "start": "", "due": "", "origin": null, "citationEvidence": [{"sentence": "课堂装置记录固定了杯盖与杯体的配对关系 [@CupLog#3baabb20d3d098cfeb9396e1]。", "key": "CupLog", "occ": 0, "pid": "3baabb20d3d098cfeb9396e1", "sha": "51320800fba9ca9e44f6c4c03268c3b973e3cc72e8722023703f4bf897c01a60", "page": 1, "reason": "记录列出了杯盖状态和杯体材质。"}]}, {"id": "434cce465a774db5", "title": "2.3 同杯换盖的交叉设计", "text": "试想把研究一的杯盖摘下，直接再计十分钟。这样会让“敞口”与“水已经冷却了十分钟”重合。为此，研究二在同一区组安排两个独立起始的十分钟时段。每个时段两只杯都倒入新水，水量固定为 200 mL，计时起点均设为 80.0 °C。每只杯配一个与杯口匹配的盖子，同一杯的两次比较只切换这个盖子的状态。两个时段之间倒空杯子，设定杯体与盖子均回复室温。数据中没有记录复温时间或实际壁温，这个复位条件属于设计假设。\n\n每个时段一只有盖、另一只敞口。区组 1、4、6、7 先给玻璃杯加盖，区组 2、3、5、8 则先给陶瓷杯加盖；第二时段互换。次序按预定表平衡，未使用随机抽签。两杯在一个区组内保持各自位置，这样同一只杯子的两次读数来自同一位置。研究二只记录起温与十分钟终点，因而可以比较终点保温差，无法检验加盖是否主要改变了最初五分钟的降温。\n\n研究一的同步配对抵消了一部分轮间共同变化，代价是盖子与杯体永远绑定。研究二把固定杯体保留下来，代价是同一只杯子不能在同一时段同时有盖和敞口。次序平衡使两种状态都有同等机会遇到第一时段；若每一组的环境变化方向和幅度不同，残留的时段影响仍可能进入同杯差。下文按先后顺序再做一次描述性对照。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "3da5ed8998724eb1", "title": "2.4 温差与降温速率", "text": "主要指标为第 10 分钟的轮内温差，即用 A 杯的终点读数减去同轮 B 杯的终点读数。正值表示该轮结束时 A 杯水温较高。按相同方法计算第 5 分钟的温差，用来判断差异出现的时段。汇总时六轮等权，同时列出轮内温差的范围，使平均值可以追溯到原始记录。\n\n为了将端点温度换算成降温速度，对每杯每轮另算十分钟平均降温速率：\n\n$$\nr = \\frac{T_0 - T_{10}}{\\Delta t}\n$$\n\n式中 $T_0$ 与 $T_{10}$ 的单位均为 °C，$\\Delta t$ 为 10 min。按此定义，降温越快，$r$ 的正值越大。我们另外依次去掉一轮，重算五轮的平均终点差，检查结果是否主要由某次特别大的差值决定。六轮均为构造的课堂记录，统计量仅描述这些数值。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "6f24fb5472c5402c", "title": "2.5 同杯差与敏感性分析", "text": "令 $T_{b,c,L}$ 与 $T_{b,c,O}$ 分别表示区组 $b$ 中杯体 $c$ 在有盖和敞口条件的十分钟终温。行次序并不总是先有盖再敞口，所以必须先按状态对齐，再作减法。对玻璃和陶瓷两个杯体分别计算：\n\n$$\nd_{b,c}=T_{b,c,L}-T_{b,c,O}\n$$\n\n正值说明有盖时终点较热，零表示两次记录落在同一温度刻度。另取玻璃杯的同杯差减去陶瓷杯的同杯差，得到区组内的差值之差。直接比较两个差可以回答“差别是否一样大”；分别陈述两只杯子各自是否出现正值无法代替这一步 [@Altman2003]。此处使用的是区组内配对，汇总全程保留配对关系。\n\n我们报告同杯差的算术平均数、最小值、最大值和样本标准差，后者的分母为区组数减一。另做两项核对：按预定顺序各自求均值，以及依次留下七组重算差值之差。由于作者已经指定全部数字，常规抽样置信区间或显著性检验会给读者造成有概率抽样依据的印象。本文因此报告实际区组的分散程度与删除单组后的变化，保留足够的原始读数让读者重新计算。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "125d47aa500f488c", "title": "3 Results", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "0819676a3c0f4244", "title": "3.1 六轮配对温差", "text": "各轮读数见课堂测量记录 [@CupLog#be1c7d6071db31ca5b50580f]。首轮两杯同从 80.0 °C 开始，5 分钟读数为 75.5 和 73.5 °C，10 分钟为 72.0 和 68.0 °C。首轮 A、B 两杯分别下降 8.0 和 12.0 °C，对应速率为 0.8 和 1.2 °C/min。表 1 汇总全部六轮，首轮可以作为复算表中指标的例子。\n\n**表 1　六轮配对读数的汇总**\n\n| 指标 | A 有盖玻璃杯 | B 敞口陶瓷杯 |\n|---|---:|---:|\n| 起始平均水温（°C） | 80.00 | 80.00 |\n| 第 5 分钟平均水温（°C） | 75.50 | 73.67 |\n| 第 10 分钟平均水温（°C） | 71.83 | 68.00 |\n| 十分钟平均降温速率（°C/min） | 0.82 | 1.20 |\n\n每轮中途读数都是 A 高于 B，六轮平均差为 1.83 °C。到终点时六个配对差依次为 4、3、4、5、4 和 3 °C，平均为 3.83 °C。各轮的两个终点见[图 2](#fig-0000000000000002)。\n\n![六轮终点温度，方块为 B 杯，圆点为 A 杯](figures/endpoints.png) <a id=\"fig-0000000000000002\"></a>\n\n**图注** 每一行是一轮观察，横线的长度是同一轮的终点温差。这里的连线表示两杯配对关系，时间固定在第 10 分钟。\n\n第 4 轮的差值最大。该轮 A 的终点仍是常见的 72 °C，B 则降到六轮最低的 67 °C。去掉这一轮，其余五轮平均终点差为 3.60 °C。依次去掉其他各轮后，所得五轮均值最高为 4.00 °C。六种重算都保留了相同方向。表中的均值保留两位小数以便复算；单次记录的分辨率仍为 0.5 °C。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 1, "refs": [], "start": "", "due": "", "origin": null, "citationEvidence": [{"sentence": "各轮读数见课堂测量记录 [@CupLog#be1c7d6071db31ca5b50580f]。", "key": "CupLog", "occ": 0, "pid": "be1c7d6071db31ca5b50580f", "sha": "51320800fba9ca9e44f6c4c03268c3b973e3cc72e8722023703f4bf897c01a60", "page": 2, "reason": "表内给出两杯在十分钟时的终点读数。"}]}, {"id": "bb250e5bad074e92", "title": "3.2 时间轨迹与配对关系", "text": "若读者只看到终点平均值，会漏掉比较如何随时间展开。用每杯的平均起温减去五分钟均温，A、B 前半段分别下降 4.50 与 6.33 °C。后半段用中途均温减去终点均温，降幅分别为 3.67 与 5.67 °C。两个时段中，B 杯的水都下降更多。末段两杯降幅之差为 2.00 °C，恰好等于中途到终点期间两杯温差的增量。用“还剩多少温差”和“这段时间降了多少”两种读法能互相校验。\n\n研究一还有一个便于误解的例子。第 3 轮的玻璃杯终点最高，为 73 °C；这一轮陶瓷杯也相对较热，为 69 °C。它们的差仍是常见的 4 °C。若从两列中分别挑最高和最低值，会把第 3 轮的玻璃杯与第 4 轮的陶瓷杯拼在一起，得到 6 °C，却没有一轮出现过这样的配对差。保留行号可以防止这种错配，也保留了一轮内两杯共同经历的环境条件。\n\n只有三个时点还不足以区分多种冷却曲线。比如，前五分钟的大部分降温可以集中在最初一分钟，也可以较均匀地分布在五分钟内，两种过程都可能给出表 1 的中途读数。因此，本文用净变化和区间平均速率描述过程，避免从这三个时点推算某一瞬间的散热功率。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "ac18bb12244d4b2e", "title": "3.3 八组同杯比较", "text": "第 1 组给出一例完整的读法。第一时段玻璃杯有盖为 72.0 °C，陶瓷杯敞口为 68.5 °C。第二时段玻璃杯敞口为 70.0 °C，陶瓷杯有盖为 70.0 °C。若直接比较第一时段左右两杯，答案会是 3.5 °C。若沿同一只玻璃杯跨时段比较，答案是 2.0 °C；陶瓷杯的同杯差为 1.5 °C。把后两个差相减得到 0.5 °C。三个减法都使用相同记录，却分别代表装置差、同杯状态差以及两只杯对换盖的差异。\n\n**表 2　同一只杯子在八个区组内换盖后的十分钟读数**\n\n| 杯体 | 敞口均温（°C） | 有盖均温（°C） | 同杯差均值（°C） | 同杯差标准差（°C） | 同杯差范围（°C） |\n|---|---:|---:|---:|---:|---:|\n| 玻璃杯 | 70.13 | 71.81 | 1.69 | 0.53 | 1.0 至 2.5 |\n| 陶瓷杯 | 68.56 | 69.88 | 1.31 | 0.65 | 0.0 至 2.0 |\n\n注。先用未舍入读数逐组相减再求均值。各列独立四舍五入，因此用表内已舍入的两列均温相减，末位可能与差值列相差 0.01 °C。\n\n玻璃杯的八个同杯差都为正值。陶瓷杯有七个正值，第 5 组两种状态都是 68.5 °C。同组玻璃杯的同杯差却有 2.0 °C，是两杯反应最不一致的一组。[图 3](#fig-0000000000000003)保留八组的所有点，可以看到第 2 和第 6 组方向反过来，陶瓷杯的加盖差更大。\n\n![八个区组中两只杯子的同杯差，圆点为玻璃杯，方块为陶瓷杯](figures/crossover.png) <a id=\"fig-0000000000000003\"></a>\n\n**图注** 每一行代表一个区组，横轴表示同杯有盖终温减敞口终温。为让重合值可见，同一行的两种符号在垂直方向略微错开。横轴上的零表示两次读数一致。\n\n逐组计算玻璃杯减陶瓷杯的同杯差之差，依次为 0.5、−1.0、1.5、0.0、2.0、−1.0、1.0 和 0.0 °C。均值为 0.38 °C，样本标准差为 1.09 °C。在四组中玻璃杯的差更大，在两组中陶瓷杯的差更大，另有两组持平。因而仅报一个正均值会遮住方向的不一致。即使实验数据来自实体杯，这样的比较也只直接涉及被测的两个杯体。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "555f63a4ab924bbd", "title": "3.4 顺序与读数分辨率", "text": "先检查结果是否集中在一种顺序。表 3 的行按第一时段哪只杯有盖划分，在每一行中仍按“有盖减敞口”计算两个时段的差。两种次序下，两只杯子的平均同杯差均为正值。陶瓷杯的两行相差约 0.38 °C，小于一个单次记录步长，但这是四个区组均值之间的差，不能据此说次序没有影响。\n\n**表 3　按第一时段加盖对象分层的平均同杯差**\n\n| 第一时段有盖的杯体 | 区组编号 | 玻璃杯同杯差（°C） | 陶瓷杯同杯差（°C） |\n|---|---|---:|---:|\n| 玻璃杯 | 1、4、6、7 | 1.63 | 1.50 |\n| 陶瓷杯 | 2、3、5、8 | 1.75 | 1.13 |\n\n再将八组轮流各去掉一组。去掉第 5 组时，剩下七组的平均差值之差最小，为 0.14 °C；去掉第 2 或第 6 组时最大，为 0.57 °C。这个范围描述同一张表中单个区组的影响。它没有刻画换一批杯子时的变化，也不能当作置信区间。尤其不能把第 5 组当成异常值删除，因为这组恰好说明了一个被平均数掩盖的结果。\n\n最后考虑读数刻度。若真实仪器按最近的 0.5 °C 四舍五入，单次读数的舍入误差至多约为 0.25 °C。只计这项误差时，一个由两次读数相减得到的同杯差最多可偏离约 0.50 °C。陶瓷杯第 5 组记为零，就仍然允许一个未被刻度分开的细小差别。均值保留两位小数便于核对算术，不能把温度计的实际分辨率提高到百分之一度。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "ed1aba741f424517", "title": "4 Discussion", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "fbfe9158b1ea430f", "title": "4.1 两套装置的温差能说明什么", "text": "从第 5 分钟到第 10 分钟，两套配置的平均温差又增加了 2.00 °C。无论从六轮总体还是从逐轮配对看，有盖玻璃杯里的水在终点都较热。若以十分钟平均速率衡量，两者每分钟相差约 0.38 °C。\n\n杯盖减缓了降温。", "format": "md", "parent": "ed1aba741f424517", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "cdca574a02f74a63", "title": "4.2 参照杯与温差分解", "text": "回到最初的选择：如果可用的只有研究一桌面上的两套装置，它们的十分钟平均差为 3.83 °C。如果实际决策是给研究二中现有的一只玻璃杯加盖，直接相关的读数变成 1.69 °C。把两个数字按大小并排并无问题，但用后者除以前者来宣布“杯盖解释了百分之几”缺少依据。两个比较来自分开构造的轮次，没有共同的同期敞口基准，也没有规定盖子与杯体的作用可以相加。\n\n研究二自身可以给出一次清晰的算术拆分。在同一组数据中，有盖玻璃杯与敞口陶瓷杯的总体均温相差 3.25 °C。沿玻璃杯这一条路径，其中 1.6875 °C 是玻璃杯自身的两种盖子状态差，另外 1.5625 °C 是两个杯子都敞口时的均温差。若改走另一条路径，先比较有盖的两只杯再改变陶瓷杯的状态，则相应的两段为 1.9375 与 1.3125 °C。两条路径相加都得到 3.25 °C，但给“加盖”分到的那一段并不相同。这说明分解依赖所选的参照杯；相同的总差本身没有唯一的原因占比。\n\n这个例子还揭示了图 2 与图 3 的区别。图 2 的每个点是一只杯子在某一时刻的实际记录温度，两个点之间的水平距离才是装置差。图 3 中每个点本身就由两条记录相减而来，两点的距离又多做了一次比较。先问图上的一个点对应原始表中的几行，是从图回到证据的一条简便路径。", "format": "md", "parent": "ed1aba741f424517", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "0e33a4806303429a", "title": "4.3 研究局限与后续检验", "text": "研究一的三个时点足以比较前后两个五分钟内的净变化，却无法还原任意一分钟的冷却速度。同一对杯子重复六次，也无法估计不同玻璃杯或陶瓷杯之间的差异。因此，十分钟均值不宜外推到其他容量、初温或更长的放置时间。\n\n杯具取样是最重要的边界。同一只玻璃杯反复换水可以显示这一只杯子在设定条件下的波动，不能代表玻璃这一材质的杯间变异。杯口尺寸、壁厚、杯盖的密合程度都和杯体身份绑定。在当前设计中，把杯子标签从“玻璃”和“陶瓷”改成“甲”和“乙”，所有计算仍然成立。这提醒我们，材质一词在表中是识别物件的标记；要对材质作结论，还需每种材质有多个独立杯体，并记录几何尺寸。\n\n其次，研究二把起温和复位作为已满足的条件。真实测量中，盖子凝结的水滴回流、探头穿过杯盖的开孔、两时段间杯壁的余热，都有可能改变读数。现有表格没有质量损失、湿度、风速或壁温，不能区分这些解释。若目的是解释蒸发，应在加盖条件下连盖称量完整装置，并明确如何处理附着在盖内的水；否则，揭盖时取走的水滴也会进入看似“蒸发”的质量差。\n\n若把这个问题带进真实课堂，优先增加的信息取决于所问的问题。要检验这两只杯子的加盖差能否再现，可以重复两时段设计，用预先生成的随机表决定先后，记录每段的室温与壁温，并为缺测和重测预先约定处理方法。要讨论材质，则应把资源用在获取多个独立杯体上，并让每只杯都经历两种盖子状态。增加同一只杯的读数频率有助于描绘曲线，却无法替代新增杯体。", "format": "md", "parent": "ed1aba741f424517", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "d0692f3c016e4b78", "title": "5 Conclusion", "text": "在第一张虚构记录表里，有盖玻璃杯在六轮中都比敞口陶瓷杯保持更高的十分钟终温。第二张表补上了同一只杯敞口与有盖两种状态，得到玻璃杯 1.69 °C、陶瓷杯 1.31 °C 的平均同杯差。区组中出现了持平和次序反转，结果的适用对象始终是给定条件下的两只指定杯子。读完这两张表，作者可以明确指出哪个数字回答哪个问题，也能解释为什么还不能凭这些数字给现实中的杯子排出保温名次。", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "5ca1124417434d40", "title": "6 Data Availability", "text": "《温度记录.csv》含研究一的十二条杯次轨迹；《课堂测量记录》保留同一项研究的装置页和逐轮读数页。《交叉实验.csv》按区组、时段、杯体、盖子状态列出研究二的三十二个终点。随附的《复算.py》可以只用 Python 标准库从两表重算正文数值。图 1 是原创装置示意，图 2 和图 3 分别取自两份原始表。本文未招募参与者，未实施实物实验，也未在事前注册分析方案。下列正式出版物提供物理与方法背景；课堂记录为本例自编附件。", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}], "versions": [{"id": "v34"}], "exhibits": {"F1": {"id": "F1", "kind": "figure", "caption": "两种杯具配置", "credit": "ManuScript 原创教学示意图，使用虚构记录", "rev": 1, "block": "", "asset": "2c5146d1bb9a4ec1", "sha": "be17d5ef08ffc9fb55f3553397e270d43f339c5269a388b0fbe8f8289e5be05a", "mime": "image/png"}, "F2": {"id": "F2", "kind": "figure", "caption": "六轮配对终点温度", "credit": "ManuScript 原创教学示意图，使用虚构记录", "rev": 1, "block": "", "asset": "5f5e22cb50404078", "sha": "e0c368d0cfa1ee93475101f1c5c540ed20b5857f8d5c46bdaeea12a4e440cdee", "mime": "image/png"}, "F3": {"id": "F3", "kind": "figure", "caption": "八个区组内两只杯子的同杯差", "credit": "ManuScript 原创教学示意图，使用虚构记录", "rev": 1, "block": "", "asset": "494338893d5e427b", "sha": "2cf8b2370917306ca9c6d0b65cf1687903cd4443267acffe523479325a7225dd", "mime": "image/png"}}, "references": {"CupLog": {"key": "CupLog", "rev": 2, "title": "课堂测量记录：杯具配置与起止温度（虚构教学记录）", "author": "示例课堂", "year": "2026", "doi": "", "url": "", "editions": [{"asset": "dc1a573dd2134a10", "sha": "51320800fba9ca9e44f6c4c03268c3b973e3cc72e8722023703f4bf897c01a60", "name": "课堂测量记录.pdf", "pages": 2}], "journal": "", "volume": "", "issue": "", "pages": "", "type": ""}, "Altman2003": {"key": "Altman2003", "rev": 1, "title": "Interaction revisited: The difference between two estimates", "author": "Altman, Douglas G.; Bland, J. Martin", "year": "2003", "doi": "10.1136/bmj.326.7382.219", "url": "", "editions": [], "journal": "BMJ", "volume": "326", "issue": "7382", "pages": "219", "type": "article-journal"}, "Appelbaum2018": {"key": "Appelbaum2018", "rev": 1, "title": "Journal article reporting standards for quantitative research in psychology: The APA Publications and Communications Board task force report", "author": "Appelbaum, Mark; Cooper, Harris; Kline, Rex B.; Mayo-Wilson, Evan; Nezu, Arthur M.; Rao, Stephen M.", "year": "2018", "doi": "10.1037/amp0000191", "url": "", "editions": [], "journal": "American Psychologist", "volume": "73", "issue": "1", "pages": "3-25", "type": "article-journal"}, "Ferreira2024": {"key": "Ferreira2024", "rev": 1, "title": "How a soup bowl and a coffee cup cool down", "author": "Ferreira, José P. M.", "year": "2024", "doi": "10.1088/1361-6552/ad6ac9", "url": "", "editions": [], "journal": "Physics Education", "volume": "59", "issue": "5", "pages": "Article 055020", "type": "article-journal"}, "Lazic2018": {"key": "Lazic2018", "rev": 1, "title": "What exactly is “N” in cell culture and animal experiments?", "author": "Lazic, Stanley E.; Clarke-Williams, Charlie J.; Munafò, Marcus R.", "year": "2018", "doi": "10.1371/journal.pbio.2005282", "url": "", "editions": [], "journal": "PLOS Biology", "volume": "16", "issue": "4", "pages": "Article e2005282", "type": "article-journal"}, "Shayunusov2025": {"key": "Shayunusov2025", "rev": 1, "title": "The influence of evaporation on the cooling small cup of hot water", "author": "Shayunusov, D.; Baliga, C.; Eskin, D.; Zeng, H.; Nikrityuk, P. A.", "year": "2025", "doi": "10.1016/j.icheatmasstransfer.2025.109607", "url": "", "editions": [], "journal": "International Communications in Heat and Mass Transfer", "volume": "169", "issue": "", "pages": "Article 109607", "type": "article-journal"}}}, "02": {"blocks": [{"id": "question", "title": "杯盖能解释多少温差？固定杯具与同杯换盖的两项模拟冷却研究", "text": "ManuScript 示例课堂\n\n**原创模拟研究**　本文的装置、温度读数和审阅意见均为写作练习构造；未开展实物实验。", "format": "md", "parent": null, "purpose": "盖上杯盖，水会凉得更慢吗？", "chain": [], "writer": "author", "status": "撰写中", "rev": 3, "refs": [], "start": "", "due": "", "origin": null, "writingPlan": {"steps": [{"id": "question", "reason": "提出可检验的问题", "node": {"id": "question", "p": "root", "t": "研究问题", "detail": "盖上杯盖，水会凉得更慢吗？", "assets": ["question"]}}, {"id": "observation", "reason": "先比较两杯的实际读数", "node": {"id": "observation", "p": "root", "t": "温度观察", "detail": "按轮比较 0、5、10 分钟的温度。", "ideaOnly": true}}], "brief": "用十分钟内的温度变化比较两套杯具，再判断测量能说明什么。"}}, {"id": "021b38607b094735", "title": "摘要", "text": "将有盖玻璃杯与敞口陶瓷杯同时摆上桌，十分钟后的温差能否说明加盖有用？我们构造了两个可以逐条复算的数据集。研究一在六轮配对观察中保持两套装置不变。第 5 和第 10 分钟的平均温差分别为 1.83 和 3.83 °C，后者在各轮介于 3 至 5 °C。研究二沿用这两只杯子，在八个区组内各安排两个时段，让每只杯子各经历一次有盖和敞口条件。按同杯的两次终点相减，加盖时玻璃杯平均高 1.69 °C，陶瓷杯平均高 1.31 °C；陶瓷杯有一个区组两次读数持平。两只杯的加盖差值之差平均为 0.38 °C，逐组却有正有负。换盖比较回答了固定装置比较留下的问题，同时暴露出时段变化和杯体取样的限制。所有温度均为写作教学构造；本文展示如何定义比较、追溯原始记录和约束结论。\n\n**关键词**　配对设计、交叉比较、热水冷却、重复测量、模拟数据", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "a04159c4e1c34989", "title": "1 Intro", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "630964f150d548a5", "title": "1.1 比较对象与研究动机", "text": "把两杯水同时放到桌上，十分钟后用温度计读数，比请人判断哪杯“更烫”更容易复核。困难在于确定比较对象。若一只是带盖的玻璃杯，另一只是敞口的陶瓷杯，那么“哪一套杯具里的水保持得更热”和“单独加盖能让水保持多热”需要两种不同的实验设计。\n\n研究一先回答前一个问题。我们关心差异在各轮的方向是否一致，也关心它是到结束时才出现，还是在中途已经可见。为此，每轮都保留同一时刻的两杯读数，并将杯子左右换位。这样，一轮共同的起始条件可以随这一对读数一起保留。杯壁和盖子则始终成套使用；这一安排决定了后文能够解释哪一种差别。\n\n设想读者要作两个决定。第一个是从桌上的两套装置中挑一套，让水在十分钟后温度更高。读者可以直接比较同桌、同时开始的两个终点。第二个是手头已经有一只杯，要决定是否给它配盖。此时最相关的参照物是这只杯敞口时的表现。两种决定使用同一支温度计、同一种单位，所需的对照却不同。这也是本文把研究分两步进行的原因。\n\n全文借鉴定量研究报告规范中关于设计、分析单位、结果与限制的报告项目 [@Appelbaum2018]。研究一保留一张较容易误读的记录，研究二有意补上研究一缺少的条件。为避免用模拟材料冒充实验，下面把条件的设定、读数的构造和从读数算出的统计量分别交代。文中外部文献用于说明研究问题的来由和比较方法，所有表格内的数字来自随文提供的两份数据。", "format": "md", "parent": "a04159c4e1c34989", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "e374614296a34516", "title": "1.2 文献背景与研究问题", "text": "一杯热水冷却时，热量可以经水面、杯壁等多条途径传向周围。已有研究通过汤碗和咖啡杯讨论了日常容器中液体的冷却过程 [@Ferreira2024]。针对小杯热水的研究也把蒸发纳入冷却分析 [@Shayunusov2025]。这给出了一个值得检验的方向：改变杯口覆盖状态后，十分钟终温可能改变。要判断某次温差究竟有多少来自蒸发，还需知道水分损失及其他传热途径。仅有温度读数无法完成这项分解。\n\n杯壁、杯口与水面之间的关系也影响观察的解释。两只同容量杯子可以有不同的壁厚、杯口面积与干燥质量。相同的初始水温保证两份水从相同读数出发，却没有保证杯壁在头一分钟吸收相同的热量。即便两只杯子都敞口，也可能出现终点温差。本文故意把第一项研究的装置差别画在图上，使读者能在看结果之前就判断比较中有哪些因素一道变化。\n\n由此提出三个顺次收窄的问题。其一，两套指定装置的水温在前后两个五分钟怎样分开？其二，同一只杯子的盖子状态改变后，十分钟终点相差多少？其三，两只具体杯子的加盖差是否一致？前两个问题分别对应研究一和研究二的主要比较。第三问须先各算一个同杯差，再比较两个差；它作为探索性分析单列，因为每种材质在本例中只有一只实物原型。", "format": "md", "parent": "a04159c4e1c34989", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "a26c6ef5d9644cb6", "title": "2 Method", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "6a02fcf487b54a40", "title": "2.1 设计与数据构造", "text": "本例的“轮”指一次同时开始的双杯观察，“区组”指紧邻的两个双杯时段。两项研究均使用同一只玻璃杯与同一只陶瓷杯的虚构原型。我们先指定研究一有六轮、研究二有八个区组，再手工给出符合 0.5 °C 网格的读数，没有从文献表格摘录数值，也没有拟合真实仪器数据。选择八组是为了两种先后次序各占四组，并使读者能手工核对每一组。样本大小没有经过基于检验效能的计算。\n\n读数有意包含若干不同情况：研究一有一轮两套装置差别较大；研究二有同杯换盖后读数相同的区组，也有陶瓷杯加盖差大于玻璃杯的区组。这样的安排可以检查分析是否保留例外。数据没有缺测，各行均参与对应汇总。读者拿到的是整张设计好的教学数据表，无法据此估计某种现象在现实中的发生概率。\n\n在记录单位与分析单位之间作区分，有助于避免把重复读数误当作独立样本。一项讨论细胞和动物实验的方法研究详细区分了实验单位与重复观测 [@Lazic2018]。落实到这里，研究一有十二条杯次轨迹、三十六个温度读数，但报告的是六个同时配对的轮次。研究二有三十二个终点，构成八组，每组各给出一个玻璃杯同杯差和一个陶瓷杯同杯差。整篇论文始终只有两只不同的杯子。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "6677a7b0ad7545c9", "title": "2.2 固定杯具的配对观察", "text": "两套杯具的配置见[图 1](#fig-0000000000000001)。课堂装置记录固定了杯盖与杯体的配对关系 [@CupLog#3baabb20d3d098cfeb9396e1]。A 为带盖玻璃杯，B 为敞口陶瓷杯。每轮开始前先倒空两杯，待杯体回复室温，再分别注入 200 mL 水。两杯均读到 80.0 °C 时启动该轮计时。奇数轮把 A 放在左侧，偶数轮对换位置，六轮各使用左右位置三次。\n\n![A 杯带盖且为玻璃杯，B 杯敞口且为陶瓷杯](figures/cup-setup.png) <a id=\"fig-0000000000000001\"></a>\n\n**图注** A、B 两套固定配置。左右位置逐轮交换，杯盖状态和杯体材质始终成对出现。\n\n每轮在起始、第 5 分钟和第 10 分钟各记录一次水温，读数按 0.5 °C 为步长记入原始表。六轮使用同一对杯具，每轮换水。一个观测单位是一轮中同时比较的两杯，三个时点用于描述这一轮的过程。将同一杯的三个读数分别计为三个独立样本，会夸大实际的重复次数。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 1, "refs": [], "start": "", "due": "", "origin": null, "citationEvidence": [{"sentence": "课堂装置记录固定了杯盖与杯体的配对关系 [@CupLog#3baabb20d3d098cfeb9396e1]。", "key": "CupLog", "occ": 0, "pid": "3baabb20d3d098cfeb9396e1", "sha": "51320800fba9ca9e44f6c4c03268c3b973e3cc72e8722023703f4bf897c01a60", "page": 1, "reason": "记录列出了杯盖状态和杯体材质。"}]}, {"id": "434cce465a774db5", "title": "2.3 同杯换盖的交叉设计", "text": "试想把研究一的杯盖摘下，直接再计十分钟。这样会让“敞口”与“水已经冷却了十分钟”重合。为此，研究二在同一区组安排两个独立起始的十分钟时段。每个时段两只杯都倒入新水，水量固定为 200 mL，计时起点均设为 80.0 °C。每只杯配一个与杯口匹配的盖子，同一杯的两次比较只切换这个盖子的状态。两个时段之间倒空杯子，设定杯体与盖子均回复室温。数据中没有记录复温时间或实际壁温，这个复位条件属于设计假设。\n\n每个时段一只有盖、另一只敞口。区组 1、4、6、7 先给玻璃杯加盖，区组 2、3、5、8 则先给陶瓷杯加盖；第二时段互换。次序按预定表平衡，未使用随机抽签。两杯在一个区组内保持各自位置，这样同一只杯子的两次读数来自同一位置。研究二只记录起温与十分钟终点，因而可以比较终点保温差，无法检验加盖是否主要改变了最初五分钟的降温。\n\n研究一的同步配对抵消了一部分轮间共同变化，代价是盖子与杯体永远绑定。研究二把固定杯体保留下来，代价是同一只杯子不能在同一时段同时有盖和敞口。次序平衡使两种状态都有同等机会遇到第一时段；若每一组的环境变化方向和幅度不同，残留的时段影响仍可能进入同杯差。下文按先后顺序再做一次描述性对照。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "3da5ed8998724eb1", "title": "2.4 温差与降温速率", "text": "主要指标为第 10 分钟的轮内温差，即用 A 杯的终点读数减去同轮 B 杯的终点读数。正值表示该轮结束时 A 杯水温较高。按相同方法计算第 5 分钟的温差，用来判断差异出现的时段。汇总时六轮等权，同时列出轮内温差的范围，使平均值可以追溯到原始记录。\n\n为了将端点温度换算成降温速度，对每杯每轮另算十分钟平均降温速率：\n\n$$\nr = \\frac{T_0 - T_{10}}{\\Delta t}\n$$\n\n式中 $T_0$ 与 $T_{10}$ 的单位均为 °C，$\\Delta t$ 为 10 min。按此定义，降温越快，$r$ 的正值越大。我们另外依次去掉一轮，重算五轮的平均终点差，检查结果是否主要由某次特别大的差值决定。六轮均为构造的课堂记录，统计量仅描述这些数值。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "6f24fb5472c5402c", "title": "2.5 同杯差与敏感性分析", "text": "令 $T_{b,c,L}$ 与 $T_{b,c,O}$ 分别表示区组 $b$ 中杯体 $c$ 在有盖和敞口条件的十分钟终温。行次序并不总是先有盖再敞口，所以必须先按状态对齐，再作减法。对玻璃和陶瓷两个杯体分别计算：\n\n$$\nd_{b,c}=T_{b,c,L}-T_{b,c,O}\n$$\n\n正值说明有盖时终点较热，零表示两次记录落在同一温度刻度。另取玻璃杯的同杯差减去陶瓷杯的同杯差，得到区组内的差值之差。直接比较两个差可以回答“差别是否一样大”；分别陈述两只杯子各自是否出现正值无法代替这一步 [@Altman2003]。此处使用的是区组内配对，汇总全程保留配对关系。\n\n我们报告同杯差的算术平均数、最小值、最大值和样本标准差，后者的分母为区组数减一。另做两项核对：按预定顺序各自求均值，以及依次留下七组重算差值之差。由于作者已经指定全部数字，常规抽样置信区间或显著性检验会给读者造成有概率抽样依据的印象。本文因此报告实际区组的分散程度与删除单组后的变化，保留足够的原始读数让读者重新计算。", "format": "md", "parent": "a26c6ef5d9644cb6", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "125d47aa500f488c", "title": "3 Results", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "0819676a3c0f4244", "title": "3.1 六轮配对温差", "text": "各轮读数见课堂测量记录 [@CupLog#be1c7d6071db31ca5b50580f]。首轮两杯同从 80.0 °C 开始，5 分钟读数为 75.5 和 73.5 °C，10 分钟为 72.0 和 68.0 °C。首轮 A、B 两杯分别下降 8.0 和 12.0 °C，对应速率为 0.8 和 1.2 °C/min。表 1 汇总全部六轮，首轮可以作为复算表中指标的例子。\n\n**表 1　六轮配对读数的汇总**\n\n| 指标 | A 有盖玻璃杯 | B 敞口陶瓷杯 |\n|---|---:|---:|\n| 起始平均水温（°C） | 80.00 | 80.00 |\n| 第 5 分钟平均水温（°C） | 75.50 | 73.67 |\n| 第 10 分钟平均水温（°C） | 71.83 | 68.00 |\n| 十分钟平均降温速率（°C/min） | 0.82 | 1.20 |\n\n每轮中途读数都是 A 高于 B，六轮平均差为 1.83 °C。到终点时六个配对差依次为 4、3、4、5、4 和 3 °C，平均为 3.83 °C。各轮的两个终点见[图 2](#fig-0000000000000002)。\n\n![六轮终点温度，方块为 B 杯，圆点为 A 杯](figures/endpoints.png) <a id=\"fig-0000000000000002\"></a>\n\n**图注** 每一行是一轮观察，横线的长度是同一轮的终点温差。这里的连线表示两杯配对关系，时间固定在第 10 分钟。\n\n第 4 轮的差值最大。该轮 A 的终点仍是常见的 72 °C，B 则降到六轮最低的 67 °C。去掉这一轮，其余五轮平均终点差为 3.60 °C。依次去掉其他各轮后，所得五轮均值最高为 4.00 °C。六种重算都保留了相同方向。表中的均值保留两位小数以便复算；单次记录的分辨率仍为 0.5 °C。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 1, "refs": [], "start": "", "due": "", "origin": null, "citationEvidence": [{"sentence": "各轮读数见课堂测量记录 [@CupLog#be1c7d6071db31ca5b50580f]。", "key": "CupLog", "occ": 0, "pid": "be1c7d6071db31ca5b50580f", "sha": "51320800fba9ca9e44f6c4c03268c3b973e3cc72e8722023703f4bf897c01a60", "page": 2, "reason": "表内给出两杯在十分钟时的终点读数。"}]}, {"id": "bb250e5bad074e92", "title": "3.2 时间轨迹与配对关系", "text": "若读者只看到终点平均值，会漏掉比较如何随时间展开。用每杯的平均起温减去五分钟均温，A、B 前半段分别下降 4.50 与 6.33 °C。后半段用中途均温减去终点均温，降幅分别为 3.67 与 5.67 °C。两个时段中，B 杯的水都下降更多。末段两杯降幅之差为 2.00 °C，恰好等于中途到终点期间两杯温差的增量。用“还剩多少温差”和“这段时间降了多少”两种读法能互相校验。\n\n研究一还有一个便于误解的例子。第 3 轮的玻璃杯终点最高，为 73 °C；这一轮陶瓷杯也相对较热，为 69 °C。它们的差仍是常见的 4 °C。若从两列中分别挑最高和最低值，会把第 3 轮的玻璃杯与第 4 轮的陶瓷杯拼在一起，得到 6 °C，却没有一轮出现过这样的配对差。保留行号可以防止这种错配，也保留了一轮内两杯共同经历的环境条件。\n\n只有三个时点还不足以区分多种冷却曲线。比如，前五分钟的大部分降温可以集中在最初一分钟，也可以较均匀地分布在五分钟内，两种过程都可能给出表 1 的中途读数。因此，本文用净变化和区间平均速率描述过程，避免从这三个时点推算某一瞬间的散热功率。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "ac18bb12244d4b2e", "title": "3.3 八组同杯比较", "text": "第 1 组给出一例完整的读法。第一时段玻璃杯有盖为 72.0 °C，陶瓷杯敞口为 68.5 °C。第二时段玻璃杯敞口为 70.0 °C，陶瓷杯有盖为 70.0 °C。若直接比较第一时段左右两杯，答案会是 3.5 °C。若沿同一只玻璃杯跨时段比较，答案是 2.0 °C；陶瓷杯的同杯差为 1.5 °C。把后两个差相减得到 0.5 °C。三个减法都使用相同记录，却分别代表装置差、同杯状态差以及两只杯对换盖的差异。\n\n**表 2　同一只杯子在八个区组内换盖后的十分钟读数**\n\n| 杯体 | 敞口均温（°C） | 有盖均温（°C） | 同杯差均值（°C） | 同杯差标准差（°C） | 同杯差范围（°C） |\n|---|---:|---:|---:|---:|---:|\n| 玻璃杯 | 70.13 | 71.81 | 1.69 | 0.53 | 1.0 至 2.5 |\n| 陶瓷杯 | 68.56 | 69.88 | 1.31 | 0.65 | 0.0 至 2.0 |\n\n注。先用未舍入读数逐组相减再求均值。各列独立四舍五入，因此用表内已舍入的两列均温相减，末位可能与差值列相差 0.01 °C。\n\n玻璃杯的八个同杯差都为正值。陶瓷杯有七个正值，第 5 组两种状态都是 68.5 °C。同组玻璃杯的同杯差却有 2.0 °C，是两杯反应最不一致的一组。[图 3](#fig-0000000000000003)保留八组的所有点，可以看到第 2 和第 6 组方向反过来，陶瓷杯的加盖差更大。\n\n![八个区组中两只杯子的同杯差，圆点为玻璃杯，方块为陶瓷杯](figures/crossover.png) <a id=\"fig-0000000000000003\"></a>\n\n**图注** 每一行代表一个区组，横轴表示同杯有盖终温减敞口终温。为让重合值可见，同一行的两种符号在垂直方向略微错开。横轴上的零表示两次读数一致。\n\n逐组计算玻璃杯减陶瓷杯的同杯差之差，依次为 0.5、−1.0、1.5、0.0、2.0、−1.0、1.0 和 0.0 °C。均值为 0.38 °C，样本标准差为 1.09 °C。在四组中玻璃杯的差更大，在两组中陶瓷杯的差更大，另有两组持平。因而仅报一个正均值会遮住方向的不一致。即使实验数据来自实体杯，这样的比较也只直接涉及被测的两个杯体。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "555f63a4ab924bbd", "title": "3.4 顺序与读数分辨率", "text": "先检查结果是否集中在一种顺序。表 3 的行按第一时段哪只杯有盖划分，在每一行中仍按“有盖减敞口”计算两个时段的差。两种次序下，两只杯子的平均同杯差均为正值。陶瓷杯的两行相差约 0.38 °C，小于一个单次记录步长，但这是四个区组均值之间的差，不能据此说次序没有影响。\n\n**表 3　按第一时段加盖对象分层的平均同杯差**\n\n| 第一时段有盖的杯体 | 区组编号 | 玻璃杯同杯差（°C） | 陶瓷杯同杯差（°C） |\n|---|---|---:|---:|\n| 玻璃杯 | 1、4、6、7 | 1.63 | 1.50 |\n| 陶瓷杯 | 2、3、5、8 | 1.75 | 1.13 |\n\n再将八组轮流各去掉一组。去掉第 5 组时，剩下七组的平均差值之差最小，为 0.14 °C；去掉第 2 或第 6 组时最大，为 0.57 °C。这个范围描述同一张表中单个区组的影响。它没有刻画换一批杯子时的变化，也不能当作置信区间。尤其不能把第 5 组当成异常值删除，因为这组恰好说明了一个被平均数掩盖的结果。\n\n最后考虑读数刻度。若真实仪器按最近的 0.5 °C 四舍五入，单次读数的舍入误差至多约为 0.25 °C。只计这项误差时，一个由两次读数相减得到的同杯差最多可偏离约 0.50 °C。陶瓷杯第 5 组记为零，就仍然允许一个未被刻度分开的细小差别。均值保留两位小数便于核对算术，不能把温度计的实际分辨率提高到百分之一度。", "format": "md", "parent": "125d47aa500f488c", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "ed1aba741f424517", "title": "4 Discussion", "text": "", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "fbfe9158b1ea430f", "title": "4.1 两套装置的温差能说明什么", "text": "从第 5 分钟到第 10 分钟，两套配置的平均温差又增加了 2.00 °C。换位和逐轮重算有助于判断读数的方向是否稳定，却都保留了同一处设计限制：六轮中没有敞口玻璃杯，也没有带盖陶瓷杯。即使每轮都观察到相同的方向，杯盖与杯壁的作用仍重叠在同一个比较里。\n\n研究一中，有盖玻璃杯的平均降温速率较低。要估计单独加盖的温差，应看研究二中同一只杯子的两次终点读数。", "format": "md", "parent": "ed1aba741f424517", "purpose": "", "chain": [], "writer": "author", "status": "撰写中", "rev": 1, "refs": [], "start": "", "due": "", "origin": null}, {"id": "cdca574a02f74a63", "title": "4.2 参照杯与温差分解", "text": "回到最初的选择：如果可用的只有研究一桌面上的两套装置，它们的十分钟平均差为 3.83 °C。如果实际决策是给研究二中现有的一只玻璃杯加盖，直接相关的读数变成 1.69 °C。把两个数字按大小并排并无问题，但用后者除以前者来宣布“杯盖解释了百分之几”缺少依据。两个比较来自分开构造的轮次，没有共同的同期敞口基准，也没有规定盖子与杯体的作用可以相加。\n\n研究二自身可以给出一次清晰的算术拆分。在同一组数据中，有盖玻璃杯与敞口陶瓷杯的总体均温相差 3.25 °C。沿玻璃杯这一条路径，其中 1.6875 °C 是玻璃杯自身的两种盖子状态差，另外 1.5625 °C 是两个杯子都敞口时的均温差。若改走另一条路径，先比较有盖的两只杯再改变陶瓷杯的状态，则相应的两段为 1.9375 与 1.3125 °C。两条路径相加都得到 3.25 °C，但给“加盖”分到的那一段并不相同。这说明分解依赖所选的参照杯；相同的总差本身没有唯一的原因占比。\n\n这个例子还揭示了图 2 与图 3 的区别。图 2 的每个点是一只杯子在某一时刻的实际记录温度，两个点之间的水平距离才是装置差。图 3 中每个点本身就由两条记录相减而来，两点的距离又多做了一次比较。先问图上的一个点对应原始表中的几行，是从图回到证据的一条简便路径。", "format": "md", "parent": "ed1aba741f424517", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "0e33a4806303429a", "title": "4.3 研究局限与后续检验", "text": "研究一的三个时点足以比较前后两个五分钟内的净变化，却无法还原任意一分钟的冷却速度。同一对杯子重复六次，也无法估计不同玻璃杯或陶瓷杯之间的差异。因此，十分钟均值不宜外推到其他容量、初温或更长的放置时间。\n\n杯具取样是最重要的边界。同一只玻璃杯反复换水可以显示这一只杯子在设定条件下的波动，不能代表玻璃这一材质的杯间变异。杯口尺寸、壁厚、杯盖的密合程度都和杯体身份绑定。在当前设计中，把杯子标签从“玻璃”和“陶瓷”改成“甲”和“乙”，所有计算仍然成立。这提醒我们，材质一词在表中是识别物件的标记；要对材质作结论，还需每种材质有多个独立杯体，并记录几何尺寸。\n\n其次，研究二把起温和复位作为已满足的条件。真实测量中，盖子凝结的水滴回流、探头穿过杯盖的开孔、两时段间杯壁的余热，都有可能改变读数。现有表格没有质量损失、湿度、风速或壁温，不能区分这些解释。若目的是解释蒸发，应在加盖条件下连盖称量完整装置，并明确如何处理附着在盖内的水；否则，揭盖时取走的水滴也会进入看似“蒸发”的质量差。\n\n若把这个问题带进真实课堂，优先增加的信息取决于所问的问题。要检验这两只杯子的加盖差能否再现，可以重复两时段设计，用预先生成的随机表决定先后，记录每段的室温与壁温，并为缺测和重测预先约定处理方法。要讨论材质，则应把资源用在获取多个独立杯体上，并让每只杯都经历两种盖子状态。增加同一只杯的读数频率有助于描绘曲线，却无法替代新增杯体。", "format": "md", "parent": "ed1aba741f424517", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "d0692f3c016e4b78", "title": "5 Conclusion", "text": "在第一张虚构记录表里，有盖玻璃杯在六轮中都比敞口陶瓷杯保持更高的十分钟终温。第二张表补上了同一只杯敞口与有盖两种状态，得到玻璃杯 1.69 °C、陶瓷杯 1.31 °C 的平均同杯差。区组中出现了持平和次序反转，结果的适用对象始终是给定条件下的两只指定杯子。读完这两张表，作者可以明确指出哪个数字回答哪个问题，也能解释为什么还不能凭这些数字给现实中的杯子排出保温名次。", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}, {"id": "5ca1124417434d40", "title": "6 Data Availability", "text": "《温度记录.csv》含研究一的十二条杯次轨迹；《课堂测量记录》保留同一项研究的装置页和逐轮读数页。《交叉实验.csv》按区组、时段、杯体、盖子状态列出研究二的三十二个终点。随附的《复算.py》可以只用 Python 标准库从两表重算正文数值。图 1 是原创装置示意，图 2 和图 3 分别取自两份原始表。本文未招募参与者，未实施实物实验，也未在事前注册分析方案。下列正式出版物提供物理与方法背景；课堂记录为本例自编附件。", "format": "md", "parent": "question", "purpose": "", "chain": [], "writer": "author", "status": "构思", "rev": 0, "refs": [], "start": "", "due": "", "origin": null}], "versions": [{"id": "v37"}], "exhibits": {"F1": {"id": "F1", "kind": "figure", "caption": "两种杯具配置", "credit": "ManuScript 原创教学示意图，使用虚构记录", "rev": 1, "block": "", "asset": "2c5146d1bb9a4ec1", "sha": "be17d5ef08ffc9fb55f3553397e270d43f339c5269a388b0fbe8f8289e5be05a", "mime": "image/png"}, "F2": {"id": "F2", "kind": "figure", "caption": "六轮配对终点温度", "credit": "ManuScript 原创教学示意图，使用虚构记录", "rev": 1, "block": "", "asset": "5f5e22cb50404078", "sha": "e0c368d0cfa1ee93475101f1c5c540ed20b5857f8d5c46bdaeea12a4e440cdee", "mime": "image/png"}, "F3": {"id": "F3", "kind": "figure", "caption": "八个区组内两只杯子的同杯差", "credit": "ManuScript 原创教学示意图，使用虚构记录", "rev": 1, "block": "", "asset": "494338893d5e427b", "sha": "2cf8b2370917306ca9c6d0b65cf1687903cd4443267acffe523479325a7225dd", "mime": "image/png"}}, "references": {"CupLog": {"key": "CupLog", "rev": 2, "title": "课堂测量记录：杯具配置与起止温度（虚构教学记录）", "author": "示例课堂", "year": "2026", "doi": "", "url": "", "editions": [{"asset": "dc1a573dd2134a10", "sha": "51320800fba9ca9e44f6c4c03268c3b973e3cc72e8722023703f4bf897c01a60", "name": "课堂测量记录.pdf", "pages": 2}], "journal": "", "volume": "", "issue": "", "pages": "", "type": ""}, "Altman2003": {"key": "Altman2003", "rev": 1, "title": "Interaction revisited: The difference between two estimates", "author": "Altman, Douglas G.; Bland, J. Martin", "year": "2003", "doi": "10.1136/bmj.326.7382.219", "url": "", "editions": [], "journal": "BMJ", "volume": "326", "issue": "7382", "pages": "219", "type": "article-journal"}, "Appelbaum2018": {"key": "Appelbaum2018", "rev": 1, "title": "Journal article reporting standards for quantitative research in psychology: The APA Publications and Communications Board task force report", "author": "Appelbaum, Mark; Cooper, Harris; Kline, Rex B.; Mayo-Wilson, Evan; Nezu, Arthur M.; Rao, Stephen M.", "year": "2018", "doi": "10.1037/amp0000191", "url": "", "editions": [], "journal": "American Psychologist", "volume": "73", "issue": "1", "pages": "3-25", "type": "article-journal"}, "Ferreira2024": {"key": "Ferreira2024", "rev": 1, "title": "How a soup bowl and a coffee cup cool down", "author": "Ferreira, José P. M.", "year": "2024", "doi": "10.1088/1361-6552/ad6ac9", "url": "", "editions": [], "journal": "Physics Education", "volume": "59", "issue": "5", "pages": "Article 055020", "type": "article-journal"}, "Lazic2018": {"key": "Lazic2018", "rev": 1, "title": "What exactly is “N” in cell culture and animal experiments?", "author": "Lazic, Stanley E.; Clarke-Williams, Charlie J.; Munafò, Marcus R.", "year": "2018", "doi": "10.1371/journal.pbio.2005282", "url": "", "editions": [], "journal": "PLOS Biology", "volume": "16", "issue": "4", "pages": "Article e2005282", "type": "article-journal"}, "Shayunusov2025": {"key": "Shayunusov2025", "rev": 1, "title": "The influence of evaporation on the cooling small cup of hot water", "author": "Shayunusov, D.; Baliga, C.; Eskin, D.; Zeng, H.; Nikrityuk, P. A.", "year": "2025", "doi": "10.1016/j.icheatmasstransfer.2025.109607", "url": "", "editions": [], "journal": "International Communications in Heat and Mass Transfer", "volume": "169", "issue": "", "pages": "Article 109607", "type": "article-journal"}}}}, "nodes": [{"id": "root", "p": null, "t": "杯盖能解释多少温差？固定杯具与同杯换盖的两项模拟冷却研究"}, {"id": "question", "p": "root", "t": "研究问题", "detail": "盖上杯盖，水会凉得更慢吗？", "assets": ["question"]}, {"id": "observation", "p": "root", "t": "温度观察", "detail": "按轮比较 0、5、10 分钟的温度。", "ideaOnly": true}, {"id": "alternative", "p": "root", "t": "可能解释", "detail": "杯盖和杯体材质是否都可能影响结果？", "ideaOnly": true}], "files": {"2c5146d1bb9a4ec1": {"name": "cup-setup.png", "data": ""}, "5f5e22cb50404078": {"name": "endpoints.png", "data": ""}, "494338893d5e427b": {"name": "crossover.png", "data": ""}}, "pins": {"3baabb20d3d098cfeb9396e1": 1, "be1c7d6071db31ca5b50580f": 2}};
